// TestAllSourcesTerminal table-tests the settle predicate (worker.go): the item
// reaches ready only when EVERY queueable source is terminal — done (namespace),
// in-ledger-cooldown, OR attempted-this-run-but-produced-no-work (the
// unavailable/skipped branch added for DEV-T08). A source with no namespace, no
// ledger row, and no recorded attempt still has genuine pending work (NOT terminal).
// Pure predicate: real module/doc structs, no doubles.
func TestAllSourcesTerminal(t *testing.T) {
	now := time.Date(2026, 8, 3, 12, 0, 0, 0, time.UTC)
	src := func(id, auth string) module.MetadataSourceBinding {
		return module.MetadataSourceBinding{PluginID: id, AuthMode: auth, Enabled: true}
	}
	withNS := func(plugin string) map[string]any {
		return map[string]any{"sources": map[string]any{plugin: map[string]any{"title": "x"}}}
	}
	stage := func(plugin, status string) map[string]any {
		return map[string]any{"plugin_id": plugin, "status": status}
	}
	withStages := func(ss ...map[string]any) map[string]any {
		return map[string]any{"_stages": append([]map[string]any{}, ss...)}
	}
	inLedger := func(item, plugin string) failureIndex {
		return failureIndex{coolKey{item, plugin}: store.FailureRow{
			ItemID: item, PluginID: plugin, NextEligibleAt: now.Add(time.Hour),
		}}
	}
	// merge overlays docs (namespace doc + stages doc) into one assertion document.
	merge := func(docs ...map[string]any) map[string]any {
		out := make(map[string]any, 4)
		for _, d := range docs {
			for k, v := range d {
				out[k] = v
			}
		}
		return out
	}

	tests := []struct {
		name string
		idx  failureIndex
		mod  module.Module
		doc  map[string]any
		want bool
	}{
		{
			name: "namespace present is terminal (success)",
			mod:  module.Module{MetadataSources: []module.MetadataSourceBinding{src("tv-parser", "")}},
			doc:  withNS("tv-parser"),
			want: true,
		},
		{
			name: "ledger cooldown is terminal",
			mod:  module.Module{MetadataSources: []module.MetadataSourceBinding{src("tmdb", "SERVER")}},
			idx:  inLedger("i", "tmdb"),
			want: true,
		},
		{
			name: "attempted-but-unavailable is terminal (NEW)",
			mod:  module.Module{MetadataSources: []module.MetadataSourceBinding{src("tmdb", "SERVER")}},
			doc:  withStages(stage("tmdb", "unavailable")),
			want: true,
		},
		{
			name: "attempted-but-skipped is terminal (NEW)",
			mod:  module.Module{MetadataSources: []module.MetadataSourceBinding{src("tmdb", "SERVER")}},
			doc:  withStages(stage("tmdb", "skipped")),
			want: true,
		},
		{
			name: "not-yet-attempted is NOT terminal (genuine pending work)",
			mod:  module.Module{MetadataSources: []module.MetadataSourceBinding{src("tmdb", "SERVER")}},
			doc:  map[string]any{},
			want: false,
		},
		{
			name: "seeded config: tv-parser done + tmdb unavailable + kinopoisk CLIENT -> terminal",
			mod: module.Module{MetadataSources: []module.MetadataSourceBinding{
				src("tv-parser", ""), src("tmdb", "SERVER"), src("kinopoisk", "CLIENT"),
			}},
			doc:  merge(withNS("tv-parser"), withStages(stage("tmdb", "unavailable"))),
			want: true,
		},
		{
			name: "tv-parser done + tmdb not-yet-attempted -> NOT terminal",
			mod: module.Module{MetadataSources: []module.MetadataSourceBinding{
				src("tv-parser", ""), src("tmdb", "SERVER"),
			}},
			doc:  withNS("tv-parser"),
			want: false,
		},
		{
			name: "CLIENT source is not queueable -> terminal regardless",
			mod:  module.Module{MetadataSources: []module.MetadataSourceBinding{src("kinopoisk", "CLIENT")}},
			doc:  map[string]any{},
			want: true,
		},
		{
			name: "most-recent stage wins: ok-then-unavailable -> terminal",
			mod:  module.Module{MetadataSources: []module.MetadataSourceBinding{src("tmdb", "SERVER")}},
			doc:  withStages(stage("tmdb", "ok"), stage("tmdb", "unavailable")),
			want: true,
		},
		{
			name: "ok stage without namespace is NOT terminal (success via namespace only)",
			mod:  module.Module{MetadataSources: []module.MetadataSourceBinding{src("tmdb", "SERVER")}},
			doc:  withStages(stage("tmdb", "ok")),
			want: false,
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := allSourcesTerminal(tc.idx, tc.mod, nil, tc.doc, "i", now); got != tc.want {
				t.Fatalf("allSourcesTerminal = %v, want %v", got, tc.want)
			}
		})
	}
}
